// zfa:tdd: A1:hand — hand step completed before first red certification (issue #1411)
//
// Hand-completed acceptance test for A1 (AC-1, issue
// arrrrny/zuraffa_browser#168): a widget mounted under the app shell resolves
// a ScaffoldMessengerState — no "No ScaffoldMessenger widget found" throw.
library;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zuraffa_ui/tdd/shadapp-missing-scaffoldmessenger/a1_subject.dart'
    as subject;

void main() {
  group('A1 (AC-1)', () {
    testWidgets('A1 — it resolves a `ScaffoldMessengerState` without throwing.', (
      tester,
    ) async {
      final messenger = await subject.subject_a1(tester);

      // The observable outcome (issue #1488): the messenger resolved from a
      // widget mounted under the shell — asserted outside the guard.
      expect(messenger, isA<ScaffoldMessengerState>());
      expect(messenger.mounted, isTrue);
    });
  });
}

// zfa:tdd: A1:hand — hand step completed before first red certification (issue #1411)
//
// Hand-implemented scenario runner for behavior A1 (AC-1): pumps ZuraffaApp
// with a probe widget in its home route and resolves the shell's
// ScaffoldMessenger from the probe's context.
//
// The subject name is derived from the behavior id (`subject_a1`) and is
// deliberately snake_cased — the generator KNOWS the name it emits, so the
// lint its shape provably trips is suppressed here rather than renaming the
// contract surface (issue #1035).
// ignore_for_file: non_constant_identifier_names
library;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zuraffa_ui/zuraffa_ui.dart';

/// Runs the A1 scenario: mounts the app shell with a probe in the home route
/// and returns the [ScaffoldMessengerState] resolved from the probe's context.
///
/// Throws if the shell provides no `ScaffoldMessenger` ancestor — the
/// condition reported in arrrrny/zuraffa_browser#168.
Future<ScaffoldMessengerState> subject_a1(WidgetTester tester) async {
  late BuildContext probeContext;
  await tester.pumpWidget(
    ZuraffaApp(
      showViolationChrome: false,
      home: Scaffold(
        body: Builder(
          builder: (context) {
            probeContext = context;
            return const SizedBox.shrink();
          },
        ),
      ),
    ),
  );
  return ScaffoldMessenger.of(probeContext);
}
